915	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
916	// 只有完整保存成功后调用方才会向用户报告成功。
917	func (s *state) save() error {
918		if err := s.validate(); err != nil {
919			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
920		}
921		data, err := json.MarshalIndent(s, "", "  ")
922		if err != nil {
923			return fmt.Errorf("序列化数据失败: %w", err)
924		}
925		data = append(data, '\n')
926	
927		tmp := s.path + ".tmp"
928		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
929		if err != nil {
930			return fmt.Errorf("写入临时数据文件失败: %w", err)
931		}
932		if _, err := f.Write(data); err != nil {
933			f.Close()
934			os.Remove(tmp)
935			return fmt.Errorf("写入临时数据文件失败: %w", err)
936		}
937		if err := f.Sync(); err != nil {
938			f.Close()
939			os.Remove(tmp)
940			return fmt.Errorf("同步数据文件失败: %w", err)
941		}
942		if err := f.Close(); err != nil {
943			os.Remove(tmp)
944			return fmt.Errorf("关闭数据文件失败: %w", err)
945		}
946		if err := os.Rename(tmp, s.path); err != nil {
947			os.Remove(tmp)
948			return fmt.Errorf("替换数据文件失败: %w", err)
949		}
950		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
951			dir.Sync()
952			dir.Close()
953		}
954		return nil
955	}
