790	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
791	func parseAmount(text string) (int64, error) {
792		text = strings.TrimSpace(text)
793		amount, err := strconv.ParseInt(text, 10, 64)
794		if err != nil {
795			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
796		}
797		if amount == 0 {
798			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
799		}
800		return amount, nil
801	}
