987	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
988	func parsePositiveAmount(text string) (int64, error) {
989		text = strings.TrimSpace(text)
990		amount, err := strconv.ParseInt(text, 10, 64)
991		if err != nil {
992			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
993		}
994		if amount <= 0 {
995			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
996		}
997		return amount, nil
998	}
