1417	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1418	// 以及前后分配涉及月份的当前余额。
1419	func printCorrection(c *correction, s *state) {
1420		p := s.Payments[c.PaymentID] // 载入时已校验存在
1421		before := allocationBefore(s, c)
1422		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1423		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1424			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1425		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1426		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1427		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1428		fmt.Fprintln(stdout, "涉及月份当前余额：")
1429		for _, m := range unionMonths(before, c.Allocations) {
1430			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1431			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1432			received, _ := paymentReceived(s, p.CustomerID, m)
1433			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1434				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1435				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1436		}
1437	}
