func cmdBillReconcile(dir, customerID, startMonth, endMonth string, seqArgs []string) error {
	if !validMonth(startMonth) {
		return fmt.Errorf("起始账期 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", startMonth)
	}
	if !validMonth(endMonth) {
		return fmt.Errorf("截止账期 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", endMonth)
	}
	if endMonth < startMonth {
		return fmt.Errorf("起始账期 %s 晚于截止账期 %s，账期范围包含首尾且起月不得晚于止月", startMonth, endMonth)
	}

	s, err := loadStore(dir)
	if err != nil {
		return err
	}
	cust, ok := s.Customers[customerID]
	if !ok {
		return fmt.Errorf("客户标识 %q 不存在", customerID)
	}

	// 起止操作序号使用调整/收款/更正及其撤销共用的已保存全局序号：省略表示
	// 0 至存档最新序号；须满足 0 ≤ 起点 ≤ 终点 ≤ 存档全局序号上限，因其他
	// 客户或月份操作造成的序号空档合法。
	startSeq, endSeq := int64(0), s.NextSeq
	seqDesc := "省略，按 0 至存档最新序号"
	if len(seqArgs) == 2 {
		from, err := parseReconSeq(seqArgs[0], "起始操作序号")
		if err != nil {
			return err
		}
		to, err := parseReconSeq(seqArgs[1], "截止操作序号")
		if err != nil {
			return err
		}
		if from > to {
			return fmt.Errorf("起始操作序号 %d 晚于截止操作序号 %d，须满足 0 ≤ 起点 ≤ 终点", from, to)
		}
		if to > s.NextSeq {
			return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", to, s.NextSeq)
		}
		startSeq, endSeq = from, to
		seqDesc = "指定"
	}

	// 只选择该客户账期范围内当前已存在的账单，不补结算、不按操作时间筛选。
	var months []string
	for _, b := range s.Bills {
		if b.CustomerID == customerID && b.Month >= startMonth && b.Month <= endMonth {
			months = append(months, b.Month)
		}
	}
	sort.Strings(months)

	// 输出前核验所有选中账单的完整流水：任何异常（即使发生在终点序号之后）
	// 都拒绝，不输出部分报表。
	type reconBill struct {
		b          *bill
		events     []ledgerEvent
		startPay   int64
		startRecv  int64
		endPay     int64
		endRecv    int64
	}
	bills := make([]reconBill, 0, len(months))
	for _, m := range months {
		b := s.Bills[billKey(customerID, m)]
		events, err := billLedger(s, b)
		if err != nil {
			return err
		}
		rb := reconBill{b: b, events: events}
		rb.startPay, rb.startRecv = ledgerBalanceAt(b, events, startSeq)
		rb.endPay, rb.endRecv = ledgerBalanceAt(b, events, endSeq)
		bills = append(bills, rb)
	}

	// 区间内（起点之后、终点以内）的账后操作：调整仅纳入所属账期在范围内
	// 的操作；收款按登记时分配、撤销按撤销时最新分配、更正按前后分配判断
	// 是否涉及范围。
	inRange := func(m string) bool { return m >= startMonth && m <= endMonth }
	inInterval := func(seq int64) bool { return seq > startSeq && seq <= endSeq }
	var ops []reconEvent
	for _, a := range s.Adjustments {
		if a.CustomerID != customerID || !inRange(a.Month) {
			continue
		}
		if inInterval(a.Seq) {
			ops = append(ops, reconEvent{
				seq: a.Seq, kind: "调整", refID: a.ID, note: a.Reason,
				changes: []reconMonthChange{{month: a.Month, deltaPayable: a.Amount}},
			})
		}
		if a.Revoked && inInterval(a.RevokeSeq) {
			neg, err := neg64(a.Amount)
			if err != nil {
				return fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出报表", a.ID, a.Amount)
			}
			ops = append(ops, reconEvent{
				seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID, note: a.RevokeReason, linkSeq: a.Seq,
				changes: []reconMonthChange{{month: a.Month, deltaPayable: neg}},
			})
		}
	}
	for _, p := range s.Payments {
		if p.CustomerID != customerID {
			continue
		}
		if inInterval(p.Seq) {
			// 多月汇款只按范围内分配计入实收，不按汇款总额重复累加。
			var changes []reconMonthChange
			for _, al := range p.Allocations {
				if inRange(al.Month) {
					changes = append(changes, reconMonthChange{month: al.Month, deltaReceived: al.Amount, alloc: al.Amount})
				}
			}
			if len(changes) > 0 {
				ops = append(ops, reconEvent{
					seq: p.Seq, kind: "收款", refID: p.ID, note: p.Note, payTotal: p.Total, changes: changes,
				})
			}
		}
		// 以登记分配为起点按序号回放更正，每次更正按前后分配判断是否涉及
		// 范围：范围内转移即使汇总变化为 0 也保留，跨范围转入或转出按实际
		// 差额计入。
		running := p.Allocations
		for _, c := range correctionsFor(s, p.ID) {
			before := running
			running = c.Allocations
			if !inInterval(c.Seq) {
				continue
			}
			var changes []reconMonthChange
			for _, m := range unionMonths(before, c.Allocations) {
				if !inRange(m) {
					continue
				}
				b4, af := allocAmountFor(before, m), allocAmountFor(c.Allocations, m)
				if b4 == 0 && af == 0 {
					continue
				}
				changes = append(changes, reconMonthChange{
					month: m, deltaReceived: af - b4, beforeAlloc: b4, afterAlloc: af,
				})
			}
			if len(changes) > 0 {
				ops = append(ops, reconEvent{
					seq: c.Seq, kind: "更正", refID: c.ID, note: c.Reason, payID: p.ID, changes: changes,
				})
			}
		}
		// 撤销取消的是撤销发生时的最新分配（终点之后的更正不提前影响）。
		if p.Revoked && inInterval(p.RevokeSeq) {
			var changes []reconMonthChange
			for _, al := range running {
				if inRange(al.Month) {
					changes = append(changes, reconMonthChange{month: al.Month, deltaReceived: -al.Amount, alloc: al.Amount})
				}
			}
			if len(changes) > 0 {
				ops = append(ops, reconEvent{
					seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID, note: p.RevokeReason,
					linkSeq: p.Seq, payTotal: p.Total, changes: changes,
				})
			}
		}
	}
	sort.Slice(ops, func(i, j int) bool { return ops[i].seq < ops[j].seq })

	// 汇总以 128 位整数精确累加：单账单余额保证在有符号 64 位内，多账单
	// 合计可能超出，仍须精确输出。
	sumOrig := int128Of(0)
	startPaySum, startRecvSum := int128Of(0), int128Of(0)
	endPaySum, endRecvSum := int128Of(0), int128Of(0)
	for _, rb := range bills {
		sumOrig = sumOrig.add(int128Of(rb.b.TotalFee))
		startPaySum = startPaySum.add(int128Of(rb.startPay))
		startRecvSum = startRecvSum.add(int128Of(rb.startRecv))
		endPaySum = endPaySum.add(int128Of(rb.endPay))
		endRecvSum = endRecvSum.add(int128Of(rb.endRecv))
	}

	// 回放区间内操作，填充每次操作后的汇总余额。
	curPay, curRecv := startPaySum, startRecvSum
	for i := range ops {
		for _, ch := range ops[i].changes {
			curPay = curPay.add(int128Of(ch.deltaPayable))
			curRecv = curRecv.add(int128Of(ch.deltaReceived))
		}
		ops[i].afterPay, ops[i].afterRecv = curPay, curRecv
	}
	// 操作变化与逐月余额来自同一批已核验流水，终点处必然一致。
	if curPay != endPaySum || curRecv != endRecvSum {
		return fmt.Errorf("区间内操作汇总与逐月终点余额不一致，数据异常，拒绝输出报表")
	}

	printReconcile(cust, startMonth, endMonth, startSeq, endSeq, seqDesc, s.NextSeq, bills, sumOrig, startPaySum, startRecvSum, endPaySum, endRecvSum, ops)
	return nil
}
