func parseReconSeq(text, name string) (int64, error) {
	v, err := strconv.ParseInt(strings.TrimSpace(text), 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%s %q 不是非负整数: %w", name, text, err)
	}
	if v < 0 {
		return 0, fmt.Errorf("%s不能为负数，收到 %d", name, v)
