	h.runExpectErr("bill", "reconcile", "c1", "2026-01", "2026-01")
	// 失败不改写存档。
	after, err := os.ReadFile(h.statePath())
	if err != nil {
		t.Fatal(err)
	}
	if string(before) != string(after) {
